USERS = {1: {"id": 1, "name": "Анна"}, 2: {"id": 2, "name": "Борис"}}


def api(method, url, body=None):
    parts = url.strip("/").split("/")
    if parts[0] != "users":
        return 404, {"error": "нет такого адреса"}

    if len(parts) == 1:
        if method == "GET":
            return 200, list(USERS.values())
        if method == "POST":
            new_id = max(USERS, default=0) + 1
            USERS[new_id] = {"id": new_id, **body}
            return 201, USERS[new_id]
        return 405, {"error": "метод не разрешён"}
    user_id = int(parts[1])
    if user_id not in USERS:
        return 404, {"error": "пользователь не найден"}
    if method == "GET":
        return 200, USERS[user_id]
    if method == "DELETE":
        del USERS[user_id]
        return 204, None
    return 405, {"error": "метод не разрешён"}



requests = [
    ("POST", "/users", {"name": "Вера"}),
    ("GET", "/users/3", None),
    ("DELETE", "/users/3", None),
    ("DELETE", "/users/3", None),
    ("PATCH", "/users/2", None),
    ("GET", "/orders", None),
]
for method, url, body in requests:
    status, _ = api(method, url, body)
    print(method, url, status)
